 def update(numbers,kind,reason):
  for n in numbers:d[n].update(disposition=kind,rationale=reason)
 def add(n,c):d[n]['directions'].append(c);d[n].update(disposition='source-explicit-role-assertion',rationale='The named role assertion is transcribed with its message/context scope and full source conditions; no unstated counterpart is supplied.')
 def act(n,label,verb,note):d[n]['actions'].append(action(label,verb,note));d[n].update(disposition='source-explicit-role-action',rationale='The actor and action are named in this sentence; the action object and conditions are retained and are not automatically the indexed message.')
