 for n in [48,52,128]:add(n,claim('sender-to-receiver','original-message-in-duplicate-option',sender='account owner',receiver='account servicer',limitation='The clause explicitly identifies the original message direction within the Duplicate/resend option; it does not establish a different sender for a forwarded copy.'))
