 add(107,claim('sender-to-receiver','original-message-in-duplicate-option',sender='market infrastructure',receiver='direct participant',limitation='Explicit original-message direction in the resend option; no new copy direction inferred.'))
 add(110,claim('intermediary-routing','current-message-routing-option',intermediary='Central Matching Utility',limitation='The source says the message may be sent through CMU; this identifies routing participation, not CMU as sender or receiver.'))
 for n in [117,119]:add(n,claim('sender-to-receiver',sender='any party in the transfer transaction',receiver='another party in the transfer transaction chain',limitation='The source deliberately uses generic contextual roles. No particular institution or named functional role is substituted.'))
 add(118,claim('receiver-only','related-transfer-cancellation-status',subject='transfer cancellation',receiver='next party',limitation='This is the meaning of a status option, not the receiver of the indexed TransferInstructionStatusReport.'))
